//go:build amd64

package floats

// Add, Sub, Div, Sqrt and ClampScalar kernels (binop.go), generated by go-asmgen
// (binop_amd64_gen.go) into binop_amd64.s. The callers pass every slice already
// sliced to the common length. They use no FMA; they share the gate of the other
// AVX2 kernels (hasAVX2FMA, kernels_amd64.go), with identical results on the
// portable path.
func addAVX2(dst, a, b []float64)
func subAVX2(dst, a, b []float64)
func divAVX2(dst, a, b []float64)
func sqrtAVX2(dst, src []float64)
func clampScalarAVX2(dst, v []float64, lo, hi float64)

func add(dst, a, b []float64) {
	if hasAVX2FMA {
		addAVX2(dst, a, b)
		return
	}
	addRef(dst, a, b)
}

func sub(dst, a, b []float64) {
	if hasAVX2FMA {
		subAVX2(dst, a, b)
		return
	}
	subRef(dst, a, b)
}

func div(dst, a, b []float64) {
	if hasAVX2FMA {
		divAVX2(dst, a, b)
		return
	}
	divRef(dst, a, b)
}

func sqrt(dst, src []float64) {
	if hasAVX2FMA {
		sqrtAVX2(dst, src)
		return
	}
	sqrtRef(dst, src)
}

func clampScalar(dst, v []float64, lo, hi float64) {
	if hasAVX2FMA {
		clampScalarAVX2(dst, v, lo, hi)
		return
	}
	clampScalarRef(dst, v, lo, hi)
}
